package com.jagan.healthcare.controller;
import com.jagan.healthcare.dto.*; import com.jagan.healthcare.model.Appointment; import com.jagan.healthcare.repository.*; import com.jagan.healthcare.security.SessionAuth; import com.jagan.healthcare.service.AppointmentService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="*") public class AdminController { private final UserAccountRepository users; private final AppointmentRepository appointments; private final DoctorRepository doctors; private final HospitalRepository hospitals; private final AppointmentService appointmentService; public AdminController(UserAccountRepository u,AppointmentRepository a,DoctorRepository d,HospitalRepository h,AppointmentService s){users=u;appointments=a;doctors=d;hospitals=h;appointmentService=s;}
 @GetMapping("/dashboard") public Map<String,Object> stats(HttpSession s){SessionAuth.requireAdmin(s);return Map.of("patients",users.countByRole("PATIENT"),"doctors",doctors.count(),"hospitals",hospitals.count(),"appointments",appointments.count());}
 @GetMapping("/appointments") public Object allAppointments(HttpSession s){SessionAuth.requireAdmin(s);return appointments.findAllByOrderByAppointmentDateAscAppointmentTimeAsc();}
 @GetMapping("/patients") public List<PatientSummary> patients(HttpSession s){SessionAuth.requireAdmin(s);return users.findAll().stream().filter(u->"PATIENT".equals(u.getRole())).map(PatientSummary::from).toList();}
 @PutMapping("/appointments/{id}/status") public Appointment updateStatus(@PathVariable Long id,@Valid @RequestBody AppointmentStatusRequest r,HttpSession s){SessionAuth.requireAdmin(s);return appointmentService.updateStatus(id,r.getStatus());}
}
